changeSet.sql:

CREATE TABLE IF NOT EXISTS outcome_types (
    id           BIGSERIAL PRIMARY KEY,
    name         VARCHAR(255) NOT NULL
);


CREATE TABLE IF NOT EXISTS outcomes (
    id               BIGSERIAL PRIMARY KEY,
    outcome_type_id  BIGINT NOT NULL,
    amount           BIGINT NOT NULL,
    CONSTRAINT fk_outcomes_outcome_type
        FOREIGN KEY (outcome_type_id)
        REFERENCES outcome_types (id)
);

CREATE INDEX IF NOT EXISTS idx_outcomes_outcome_type_id
    ON outcomes(outcome_type_id);
